// Concatenates all migrations into supabase/setup.sql so the whole database
// can be created with a single paste into the Supabase SQL editor.
// Usage: npm run db:setup-sql
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const dir = join(root, "supabase/migrations");
const files = readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();

const parts = [
  "-- Stærk50 – complete database setup (generated by scripts/build-setup-sql.mjs).",
  "-- Paste everything into Supabase → SQL Editor → New query → Run. Run it only once on a new project.",
  "-- Files included: " + files.join(", "),
  "",
];
for (const file of files) {
  parts.push(`-- >>>>>>>>>> ${file}`, readFileSync(join(dir, file), "utf8").trim(), "");
}
writeFileSync(join(root, "supabase/setup.sql"), parts.join("\n"));
console.log(`Wrote supabase/setup.sql from ${files.length} migration files.`);
